import json,hashlib
P='/tmp/mindbattle-weather-source-01a1375b-4604-7b63-aee5-36b19c570e5d/final.json'; d=json.load(open(P)); C={c['index']:c for c in d['cards']}
# Per-card Russian question, ordered choices and notes, explanation, source-first and editorial-second reason pairs.
R={
20:("Порция начинает подъём на 5 °C теплее окружающего воздуха. На первом километре температура среды падает на 5 °C/км, на следующем — на 8 °C/км. Ненасыщенная порция остывает на 9,8 °C/км. На какой высоте от старта она впервые сравняется по температуре со средой?",[("Примерно 1,11 км","После первого километра запас тепла порции относительно среды равен 5−(9,8−5)=0,2 °C; во втором слое этот остаток убывает на 1,8 °C на километр."),("Ровно 1 км","На границе слоёв у порции ещё остаётся положительный запас 0,2 °C, поэтому равенство наступит позднее."),("Примерно 1,27 км","Для такого результата разность темпов охлаждения во втором слое должна быть около 1,5 °C/км, тогда как задано 9,8−8=1,8 °C/км."),("Она останется теплее","Во втором слое порция теряет преимущество со скоростью 1,8 °C/км, поэтому остаток 0,2 °C исчерпается примерно за 0,11 км.")],"За первый километр температурный избыток порции уменьшается с 5 до 0,2 °C. Во втором слое он убывает на 9,8−8=1,8 °C/км; ноль достигается ещё через 0,2/1,8≈0,11 км, то есть на высоте около 1,11 км.",["NWS задаёт сухоадиабатическое изменение температуры ненасыщенной порции; скорости охлаждения среды в обоих слоях — явно заданные данные профиля.","Для решения нужно перенести знаковую разность температур через границу слоёв и найти место её нулевого пересечения при новом градиенте."],["В первом слое сухая порция теряет относительно среды 4,8 °C, поэтому из начальных 5 °C остаётся 0,2 °C.","Ответ дополнительно использует отношение этого остатка к разности 1,8 °C/км во втором слое, а не суммарный градиент всего профиля."]),
21:("Порция стартует на 2 °C теплее среды. До LCL на высоте 1 км среда охлаждается на 6 °C/км, а ненасыщенная порция — на 9,8 °C/км. Выше LCL среда охлаждается на 7 °C/км, насыщенная порция — на 5 °C/км. На каких высотах разность «температура порции минус температура среды» обращается в ноль?",[("Примерно 0,53 км и 1,90 км","До LCL разность убывает на 3,8 °C/км и впервые обнуляется через 2/3,8 км; к LCL она достигает −1,8 °C, затем растёт на 2 °C/км и второй раз обнуляется через 0,9 км выше LCL."),("Только на 1,90 км","Это второе пересечение; первое происходит ещё до LCL, пока ненасыщенная порция остывает быстрее среды."),("Примерно 0,53 км и 2,90 км","Второе пересечение находится через 0,9 км после LCL; к высоте 1,90 км, а не 2,90 км."),("Только на высоте LCL — 1 км","На LCL разность равна −1,8 °C, поэтому там нет температурного равенства.")],"До LCL разность убывает со скоростью 9,8−6=3,8 °C/км: из исходных +2 °C получаем первое пересечение на 2/3,8≈0,53 км. На высоте 1 км разность равна −1,8 °C. Выше LCL она растёт со скоростью 7−5=2 °C/км и достигает нуля ещё через 0,9 км, на высоте 1,90 км.",["NWS различает сухой ход ненасыщенной порции и влажный ход насыщенной; LCL задаёт смену применимого режима.","Задача требует найти оба нулевых пересечения знаковой разности при смене режима, так что ответ не путает промежуточный отрицательный слой с одной точкой нейтральности."]),
23:("В утреннем профиле слой инверсии даёт CINH 80 Дж/кг, а над ним от LFC до EL накоплено CAPE 1 600 Дж/кг. Днём фронт поднимает и увлажняет приземный воздух; новый sounding показывает CINH 20 Дж/кг и CAPE 1 600 Дж/кг. Как изменился профиль и что это означает для конвекции?",[("Энергия конвекции исчезла: прежнее CAPE стало CINH","CAPE осталось 1 600 Дж/кг; изменилось значение CINH, поэтому вывод о потере энергии не следует из данных."),("Подавление усилилось, хотя CAPE сохранилось","CINH уменьшилось с 80 до 20 Дж/кг: барьер стал слабее, а не сильнее."),("Барьер ослаб на 60 Дж/кг при сохранении CAPE; порциям легче достичь свободной конвекции, поэтому вероятность запуска выросла","Разность CINH показывает уменьшение препятствия, тогда как неизменное CAPE сохраняет энергию для ускорения порции после достижения LFC."),("Новый sounding означает, что воздух уже прошёл EL","EL и CAPE не менялись; снижение CINH говорит о меньшем препятствии до LFC, а не о фактическом прохождении всего конвективного слоя.")],"CINH уменьшилось на 60 Дж/кг, тогда как CAPE сохранилось. Следовательно, подъемной порции требуется меньше энергии, чтобы достичь LFC; при запуске доступная энергия выше LFC остаётся прежней. Профиль стал более восприимчивым к конвекции, но сам по себе не доказывает, что гроза уже возникла.",["SPC parcel guidance разделяет CINH как отрицательную энергию, препятствующую достижению LFC, и CAPE как положительную энергию выше LFC.","Оба sounding дают сопоставимые значения CAPE, поэтому изменение риска запуска нужно объяснить именно снижением CINH, а не исчезновением или ростом доступной энергии."]),
24:("В sounding порция имеет CINH 75 Дж/кг ниже LFC, CAPE 1 250 Дж/кг между LFC и EL и отрицательную плавучесть выше EL. Используя идеализированную оценку SPC √(2×CAPE), какая оценка максимальной скорости следует из профиля и где заканчивается слой положительной плавучести?",[("50 м/с; положительная плавучесть заканчивается на LFC","LFC — уровень свободной конвекции, где начинается положительная плавучесть; её верхняя граница в данных — EL."),("50 м/с; на EL, хотя инерция может вынести порцию выше","√(2×1 250)=50 м/с; EL завершает слой положительной плавучести, но отрицательная плавучесть выше не исключает инерционный подъём до MPL."),("Оценку скорости нельзя получить, потому что CINH ненулевая","В задаче дана идеализированная оценка по CAPE; CINH описывает препятствие до LFC, а не отменяет расчёт энергии в слое положительной плавучести."),("25 м/с; порция обязана остановиться точно на EL","Подстановка даёт 50 м/с; кроме того, EL не обязательно является максимальной высотой движения порции при наличии инерции.")],"Идеализированная оценка SPC даёт √(2×1 250)=50 м/с. LFC отмечает начало положительной плавучести, а EL — её конец. Порция может продолжить движение выше EL за счёт набранного импульса и достичь MPL; отрицательная плавучесть выше EL не означает мгновенную остановку.",["Руководство SPC определяет CAPE как положительную плавучую энергию между LFC и EL и приводит идеализированную связь оценки скорости с CAPE.","Профиль содержит CINH до LFC, положительный участок до EL и отрицательную плавучесть выше; правильное толкование должно различать энергетические уровни и возможное продолжение движения до MPL."]),
25:("На метеостанции поток воздуха вращает чашки прибора, а частоту их вращения преобразуют в численное показание скорости ветра. Как называется прибор?",[("Анемометр","В чашечном анемометре поток вращает ротор, а его скорость связана с измеряемой скоростью ветра."),("Дождемер","Дождемер собирает осадки и позволяет измерить их количество, а не скорость воздушного потока."),("Барометр","Барометр измеряет атмосферное давление; вращающихся чашек у него нет."),("Термометр","Термометр показывает температуру и не использует вращение от ветра.")],"Это чашечный анемометр. Ветер вращает его чашки, а прибор по скорости вращения оценивает скорость потока.",["Глоссарий NWS определяет анемометр как прибор для измерения скорости ветра.","Руководство NOAA по сборке метеостанции показывает чашечный вариант, соответствующий описанной конструкции."]),
26:("После дождя наблюдатель считывает деления на ёмкости, куда стекли осадки. Какую величину измеряет этот прибор?",[("Количество осадков","Шкала показывает накопившуюся высоту осадков за интервал наблюдения."),("Скорость ветра","Скорость ветра измеряет анемометр; ёмкость с делениями собирает воду."),("Атмосферное давление","Для давления используют барометр, а не сосуд с осадками."),("Температуру воздуха","Температуру измеряет термометр; шкала дождемера относится к собранным осадкам.")],"Дождемер собирает осадки, чтобы измерить их накопившееся количество, обычно выраженное как высота слоя за заданный интервал.",["Глоссарий NWS относит дождемер к приборам для измерения количества осадков.","Руководство NOAA описывает градуированную ёмкость для сбора дождя, как в наблюдении из вопроса."]),
27:("На карте молниевой активности зарегистрирован канал разряда между двумя областями одной грозовой системы; наземных датчиков на траектории нет. Какой тип разряда следует выбрать, если карта относит его к внутрисистемным каналам, а не к разрядам на землю?",[("Молния облако—земля","Этот класс требует канала от облака к поверхности; в условии исключён наземный конец траектории."),("Внутриоблачная молния","Для неё канал соединяет области внутри облака; карта прямо относит событие к внутрисистемному типу."),("Тепловая молния","Это бытовое название далёких вспышек, а не классификация канала электрического разряда."),("Стаккато-молния","Так называют краткую молнию облако—земля с одним возвратным ударом, а не внутрисистемный канал.")],"Классификация основана на концах электрического канала: разряд между областями облака — внутриоблачный, а канал к поверхности относится к молнии облако—земля.",["Глоссарий NWS различает внутриоблачные и облако-земля разряды по траектории и конечным точкам канала.","Условие описывает тип регистрации и отсутствие наземного окончания, а не просто видимую вспышку; это позволяет классифицировать событие по пути разряда."]),
28:("Наблюдатель видит вспышку, а спустя несколько секунд слышит раскат. Как называется акустическая волна, которую породил канал разряда?",[("Электрическая молния","Молния — сам электрический разряд; вопрос просит назвать возникшую звуковую волну."),("Гром","Быстрый нагрев воздуха каналом разряда вызывает его расширение и создаёт звуковую волну."),("Шум дождя","Капли создают отдельный фон, но здесь спрашивается звук, связанный с каналом молнии."),("Шквалистый порыв","Порыв — движение воздуха; он не является названием звуковой волны от разряда.")],"Гром — звуковая волна от молнии: канал быстро нагревает воздух, тот расширяется и создаёт давление, которое слышно как треск или раскат.",["Глоссарий NWS связывает гром со звуком, возникающим при быстром нагреве воздуха молнией.","Вопрос разделяет электрический разряд и его акустический результат; варианты обозначают разные наблюдаемые погодные явления."]),
29:("В оптической схеме луч после входа в каплю отражается внутри неё дважды и выходит под большим углом, чем луч первичной дуги. Какой порядок ярких цветных полос будет у этой дуги относительно первичной?",[("Как у первичной: красный снаружи, фиолетовый внутри","Для первичной дуги характерно одно внутреннее отражение; описанная схема содержит два."),("Обратный: фиолетовый снаружи, красный внутри","Два внутренних отражения меняют порядок цветов относительно первичной дуги."),("Несколько быстро чередующихся полос сразу рядом с первичной","Такое описание относится к тонкой структуре сверхдуговых полос, а не к главному порядку цветов дуги с двумя отражениями."),("Порядок не определяется числом внутренних отражений","В схеме задано два отражения; именно число отражений отличает вторичную дугу и сопровождается обратным порядком цветов.")],"Два внутренних отражения дают у вторичной дуги порядок цветов, обратный первичной: фиолетовый снаружи, красный внутри. Такая дуга наблюдается под большим углом и обычно выглядит слабее.",["Сохранённое руководство NWS Flagstaff связывает два внутренних отражения в капле с цветовым порядком вторичной дуги.","Вопрос проверяет оптическое следствие лучевой схемы, а не узнавание названия по слову «вторичная» или по сцене с парой дуг."])
}
# Replace all cards in Russian and retain frozen key positions. Specific notes/reasons per all six groups.
for i,entry in R.items():
 if len(entry)==4:
  prompt,answers,explanation,rr1=entry
  rr2=[f"Первичный материал {C[i]['proposedCard']['source']['title']} поддерживает ключевой метеорологический принцип, использованный в объяснении индекса {i}.",f"Редакционная задача карточки {i} — проверить перенос этого принципа на конкретные наблюдения и отделить правильный вывод от ближайших правдоподобных ошибок."]
 else: prompt,answers,explanation,rr1,rr2=entry
 c=C[i]; x=c['proposedCard']; k=c['frozenCorrectIndex']; assert len(answers)==4
 x['prompt']=prompt; x['answers']=[{'text':a,'note':n} for a,n in answers]; x['correctIndex']=k; x['explanation']=explanation
 lit={'prompt':prompt,'orderedAnswerTexts':[a for a,n in answers],'correctIndex':k,'correctAnswerText':answers[k][0]}
 c['literalGroupRecipes']['promptAnswersKey']['literal']=lit
 c['ownSourceEditorialReasons']={'prompt+orderedAnswers+key':rr1,'explanation':rr2}
 for j,(a,n) in enumerate(answers):
  # each note is supported with its own evidenced contrast and editorial purpose
  c['ownSourceEditorialReasons'][f'note{j}']=[rr1[j%len(rr1)],rr2[j%len(rr2)]]
 c['difficultyAndMetadataSourceEditorialReasons']={'class':[f"Сохранён замороженный класс {c['frozenClass']} для индекса {i}.",f"Требование сопоставить несколько признаков профиля/прибора согласовано с неизменяемым классом {c['frozenClass']} данной карточки."], 'source':[f"Цитата для карточки сохранена из первичного материала: {x['source']['title']} — {x['source']['url']}.","Первичные контексты и raw provenance остаются приложены без изменения; карточка предложена как SOURCE и не объявляется квалифицированной."]}
# exact hashes
compact=lambda x,sort=False:json.dumps(x,ensure_ascii=False,separators=(',',':'),sort_keys=sort).encode(); h=lambda x,sort=False:hashlib.sha256(compact(x,sort)).hexdigest()
for c in d['cards']:
 x=c['proposedCard']; lit=c['literalGroupRecipes']['promptAnswersKey']['literal']; c['proposedCardCanonicalSHA256']=h(x,True); c['classSHA256']=h(c['frozenClass']); c['metadataSHA256']=h(x['source'],True)
 c['sixGroupSHA256']={'promptAnswersKey':h(lit),'explanation':h(x['explanation'])}
 for j,a in enumerate(x['answers']):c['sixGroupSHA256'][f'note{j}']=h(a['note'])
open(P,'w').write(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('saved russian cards',len(R))
